 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_date_cal_onclick
 * @description 달력 아이콘 클릭 시 조회일자 입력란(edt_search_date)의 달력 팝업(popUpCalendar2)을 연다.
 * @param {Object} e 클릭 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_date_cal_onclick = function(e) {
    try {
        popUpCalendar2(edt_search_date);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42030.img_date_cal_onclick" });
    }
};

