/**
 * @method
 * @name btn_add_sys_msg_onclick
 * @description 메세지 관리 [신규] 버튼 클릭 시 dts_sys_msg에 행을 추가하고 CHECK 컬럼을 "T"로 설정한다.
 * @param {Object} e 클릭 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_add_sys_msg_onclick = function(e) {
    try {
        dts_sys_msg.insertRow();
        dts_sys_msg.setCellData(dts_sys_msg.getFocusedRowIndex(), "CHECK", "T");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42030.btn_add_sys_msg_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_msg_onclick
 * @description 메세지 관리 [삭제] 버튼 클릭 시 dts_sys_msg의 체크된 행을 삭제(deleteRows)한다.
 * @param {Object} e 클릭 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_delete_msg_onclick = function(e) {
    try {
        scwin.deleteRows(dts_sys_msg);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42030.btn_delete_msg_onclick" });
    }
};

/**
 * @method
 * @name btn_save_msg_onclick
 * @description 메세지 관리 [저장] 버튼 클릭 시 dts_sys_msg 변경분을 서브미션(sbm_tr_sys_msg, /sms.do)으로 저장한다.
 * @param {Object} e 클릭 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_save_msg_onclick = async function(e) {
    try {
        tr_sys_msg.KeyName = "toinb_dataid4";

        const sbmOptions = {
            id : "sbm_tr_sys_msg",
            action : "/sms.do",
            ref : "dts_sys_msg",
            target : "tr_sys_msg=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT42030.btn_save_msg_onclick" });
    }
};

