/**
 * @method
 * @name btn_msg_rcv_grp_add_onclick
 * @description 수신그룹 관리 [신규] 버튼 클릭 시 dts_msg_rcv_grp에 행을 추가하고 CHECK 컬럼을 "T"로 설정한다.
 * @param {Object} e 클릭 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_msg_rcv_grp_add_onclick = function(e) {
    try {
        dts_msg_rcv_grp.insertRow();
        dts_msg_rcv_grp.setCellData(dts_msg_rcv_grp.getFocusedRowIndex(), "CHECK", "T");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42030.btn_msg_rcv_grp_add_onclick" });
    }
};

/**
 * @method
 * @name btn_rcv_grp_memb_add_onclick
 * @description 수신자관리 [신규] 버튼 클릭 시 수신그룹이 선택되어 있으면 dts_rcv_grp_memb에 행을 추가하고 CHECK·RCV_GRP_ID를 설정하며, 미선택 시 안내 메세지를 표시한다.
 * @param {Object} e 클릭 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_rcv_grp_memb_add_onclick = function(e) {
    try {
        if (dts_msg_rcv_grp.getCellData(dts_msg_rcv_grp.getFocusedRowIndex(), "RCV_GRP_ID") !== "") {
            dts_rcv_grp_memb.insertRow();
            dts_rcv_grp_memb.setCellData(dts_rcv_grp_memb.getFocusedRowIndex(), "CHECK", "T");
            dts_rcv_grp_memb.setCellData(dts_rcv_grp_memb.getFocusedRowIndex(), "RCV_GRP_ID", dts_msg_rcv_grp.getCellData(dts_msg_rcv_grp.getFocusedRowIndex(), "RCV_GRP_ID"));
        } else {
            alert("수신그룹관리를 선택하여 주십시요.");
        }
        // dts_rcv_grp_memb.AddRow();

        // dts_rcv_grp_memb.NameValue(dts_rcv_grp_memb.RowPosition, "CHECK") = "T";

        // dts_rcv_grp_memb.NameValue(dts_rcv_grp_memb.RowPosition, "RCV_GRP_ID") = dts_msg_rcv_grp.NameValue(dts_msg_rcv_grp.RowPosition, "RCV_GRP_ID") ;	
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42030.btn_rcv_grp_memb_add_onclick" });
    }
};

/**
 * @method
 * @name btn_rcv_grp_memb_save_onclick
 * @description 수신자관리 [저장] 버튼 클릭 시 입력값 검사(dataCheck) 통과 후 dts_rcv_grp_memb 변경분을 서브미션(sbm_tr_rcv_grp_memb, /sms.do)으로 저장한다.
 * @param {Object} e 클릭 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_rcv_grp_memb_save_onclick = async function(e) {
    try {
        if (scwin.dataCheck()) {
            tr_rcv_grp_memb.KeyName = "toinb_dataid4";

            const sbmOptions = {
                id : "sbm_tr_rcv_grp_memb",
                action : "/sms.do",
                ref : "dts_rcv_grp_memb",
                target : "tr_rcv_grp_memb=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT42030.btn_rcv_grp_memb_save_onclick" });
    }
};

/**
 * @method
 * @name MxGrid_3_OnClick
 * @description 수신그룹 그리드 클릭 시 선택 그룹(RCV_GRP_ID)의 수신자 목록을 조회(rcvGrpMembSearch)한다.
