scwin.MxGrid_3_OnClick = function(row, colid) {
    try {
        scwin.rcvGrpMembSearch(dts_msg_rcv_grp.getCellData(dts_msg_rcv_grp.getFocusedRowIndex(), "RCV_GRP_ID"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42030.MxGrid_3_OnClick" });
    }
};

