/**
 * @method
 * @name grd_sys_log_OnDblClick
 * @description 시스템 로그 그리드 더블클릭 시 선택 행의 발생일시·관련소스·로그내용을 전역에 보관하고 로그 상세 팝업(smsInfo)을 연다.
 * @param {Number} row 더블클릭한 행 인덱스
 * @param {String} colid 더블클릭한 컬럼 ID
 * @returns {void}
 * @hidden N
 */
scwin.grd_sys_log_OnDblClick = function(row, colid) {
    try {
        scwin.occr_ddtm = dts_sys_log.getCellData(row, "OCCR_DDTM");
        scwin.rel_src_nm = dts_sys_log.getCellData(row, "REL_SRC_NM");
        scwin.log_contn = dts_sys_log.getCellData(row, "LOG_CONTN");
        scwin.smsInfo();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42030.grd_sys_log_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name sysLogSearch
 * @description 시스템 로그 조회 서브미션(sbm_dts_sys_log, /sms.do)을 실행하고 완료 콜백을 연결한다.
 * @returns {void}
 * @hidden N
 */
scwin.sysLogSearch = async function() {
    const sbmOptions = {
        id : "sbm_dts_sys_log",
        action : "/sms.do",
        ref : "",
        target : "dts_sys_log=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_sys_log_OnLoadCompleted(sbmRtn); // 구 콜백 연결

};

/**
 * @method
 * @name sysMsgSearch
 * @description 시스템 메세지 조회 서브미션(sbm_dts_sys_msg, /sms.do)을 실행하고 완료 콜백을 연결한다.
