///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name deleteRows
 * @description 대상 데이터리스트에서 CHECK 컬럼이 "T"인 행을 역순으로 일괄 삭제한다.
 * @param {Object} obj 대상 데이터리스트(DataList) 객체
 * @returns {void}
 * @hidden N
 */
scwin.deleteRows = function(obj) {
    for (let i = obj.getRowCount() - 1; i >= 0; i--) {
        if (obj.getCellData(i, "CHECK") === "T") obj.removeRow(i);
    }
};

