/**
 * @method
 * @name dataCheck
 * @description 수신자 신규 행의 사용자 ID(INTEG_USR_ID)가 영문·숫자로만 구성되어 있는지 검사한다.
 * @returns {Boolean} 전체 신규 행이 유효하면 true, 위반 행 발견 시 false
 * @hidden N
 */
scwin.dataCheck = function() {
    for (let i = 0; i < dts_rcv_grp_memb.getRowCount(); i++) {
        // alert(i+"==>"+dts_rcv_grp_memb.RowStatus(i));
        if (dts_rcv_grp_memb.getRowStatus(i) === 1) {
            const in_val = dts_rcv_grp_memb.getCellData(i, "INTEG_USR_ID");
            const a_len = in_val.length;
            const b_len = in_val.replace(/[^a-z0-9]/gi, '').length;
            if (a_len !== b_len || in_val.length <= 0) {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                // 
                // ********************************************************************

                /*ORG SRC: dts_rcv_grp_memb.NameString(i, "INTEG_USR_ID") = in_val.replace(/[^a-z0-9]/gi, '');*/
                X = in_val.replace(/[^a-z0-9]/gi, '');
                alert("영어, 숫자만 입력 가능합니다.");
                return false;
            }
        }
    }
    return true;
};

